#!/usr/bin/env python3
"""gen_roms.py — Convert VIC-20 and C64 ROM binaries into C header arrays.

Reads ROM files from /home/jjs/Projects/myemu/vice-roms/ and writes
C headers with uint8_t byte arrays suitable for embedding into the WASM modules.

Usage:
    python3 gen_roms.py
"""

from pathlib import Path

ROM_BASE = Path("/home/jjs/Projects/myemu/vice-roms")

ROM_SPECS = {
    "vic20_roms.h": [
        ("g_rom_vic20_char",  ROM_BASE / "VIC20/chargen-901460-03.bin"),
        ("g_rom_vic20_basic", ROM_BASE / "VIC20/basic-901486-01.bin"),
        ("g_rom_vic20_kernal", ROM_BASE / "VIC20/kernal.901486-07.bin"),
    ],
    "c64_roms.h": [
        ("g_rom_c64_char",   ROM_BASE / "C64/chargen-901225-01.bin"),
        ("g_rom_c64_basic",  ROM_BASE / "C64/basic-901226-01.bin"),
        ("g_rom_c64_kernal", ROM_BASE / "C64/kernal-901227-03.bin"),
    ],
}


def write_rom_array(out_fh, array_name, data):
    """Write a single static uint8_t array (non-const, chips_range_t requires void*)."""
    out_fh.write(f"static uint8_t {array_name}[{len(data)}] = {{\n")
    for i in range(0, len(data), 16):
        chunk = data[i : i + 16]
        hex_bytes = ", ".join(f"0x{b:02X}" for b in chunk)
        out_fh.write(f"    {hex_bytes},\n")
    out_fh.write("};\n\n")


def generate_header(header_name, specs):
    """Generate a complete ROM header file."""
    out_path = Path(__file__).resolve().parent / header_name
    with open(out_path, "w", encoding="utf-8") as fh:
        fh.write("/* Auto-generated by gen_roms.py -- DO NOT EDIT */\n")
        fh.write("#ifndef _ROM_HEADER_H_\n")
        fh.write("#define _ROM_HEADER_H_\n\n")
        fh.write("#include <stdint.h>\n\n")
        for array_name, bin_path in specs:
            data = bin_path.read_bytes()
            write_rom_array(fh, array_name, data)
        fh.write("#endif /* _ROM_HEADER_H_ */\n")
    print(f"  wrote {out_path}")


def main():
    print("gen_roms.py -- generating ROM headers\n")
    for header_name, specs in ROM_SPECS.items():
        generate_header(header_name, specs)


if __name__ == "__main__":
    main()